import React, { useState } from 'react';
import styles from '../FloatingCard/FloatingCard.module.css';
import { excelData } from '../../data';

const Block = ({
  config,
  isOpen,
  setIsOpen,
  highlightedBlock,
  setModalData,
  highlightedItem,
}) => {
  const [isHovered, setIsHovered] = useState(false);

const isSearchResult = 
  highlightedBlock === config.name.toLowerCase().replace(/\s+/g, '') ||
  highlightedBlock === config.name.toLowerCase() ||
  (highlightedItem && config.name === highlightedItem) ||
  (highlightedItem && config.dropdownItems?.includes(excelData.findIndex(item => item.name === highlightedItem))) ||
  (config.searchKeywords && config.searchKeywords.some(keyword => 
    highlightedBlock && keyword.toLowerCase().includes(highlightedBlock.toLowerCase())));

  const handleClick = (e) => {
    e.stopPropagation();
    if (config.dropdownItems) {
      const newState = !isOpen;
      setIsOpen(newState);
      
  
    }
  };

const handleDropdownItemClick = (itemName, e) => {
  e.stopPropagation();

  if (config.name === "Классификация") return;

  const noModalItems = [
    "Комплексные решения",
    "Оборудование",
    "Флотационная фабрика",
    "Модульная мобильная фабрика cPlant",
    "Скоростная флотация SkimAir"
  ];

  // Нормализуем строки для сравнения
  const normalizedItemName = itemName.trim().toLowerCase();
  const shouldPreventModal = noModalItems.some(
    item => item.trim().toLowerCase() === normalizedItemName
  );

  if (shouldPreventModal) return;

  const selectedData = excelData.find(data => data.name === itemName);
  if (!selectedData) return;

  const dropdownRect = e.currentTarget.closest(`.${styles.dropdown_list}`).getBoundingClientRect();
  
  setModalData({
    ...selectedData,
    position: {
      left: dropdownRect.right + 4,
      top: dropdownRect.top - 150,
    }
  });
};

  return (
    <div
  className={`${styles[`blok_${config.name.toLowerCase().replace(/\s+/g, '')}`]} 
  ${isSearchResult ? styles.highlighted : ''}`}
  onMouseEnter={() => setIsHovered(true)}
  onMouseLeave={() => setIsHovered(false)}
  style={{ 
    position: 'absolute',
    left: `${config.position.left}px`,
    top: `${config.position.top}px`,
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center', /* Центрирование по вертикали и горизонтали */
    width: 'auto',
    flexDirection: 'column' /* Добавлено для вертикального расположения */
  }}
>
      <div 
        className={styles[config.name.toLowerCase().replace(/\s+/g, '')]} 
        onClick={handleClick}
        style={{
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  width: '100%',
  height: '100%',
  flexDirection: 'column'
}}
      >
        <img
          className={styles[`img_${config.name.toLowerCase().replace(/\s+/g, '')}`]}
          src={(isHovered || isSearchResult) && config.hoverImage ? config.hoverImage : config.image}
          alt={config.name}
          style={{
            maxWidth: '100%',
            maxHeight: '100%',
            objectFit: 'contain'
          }}
        />

      {/* Измененная часть - menu_container теперь всегда отображается */}
      <div className={styles.context_menu} onClick={handleClick}>
        <div className={styles.menu_container}>
          <div className={styles.menu_text}>{config.name}</div>
          {config.vectorIcon && <img className={styles.vector_icon} src={config.vectorIcon} alt="Иконка" />}
        </div>
      </div>
      
      {isOpen && config.dropdownItems && (
        <div 
          className={styles.dropdown_list} 
          onMouseLeave={() => setIsOpen(false)}
          onClick={(e) => e.stopPropagation()}
        >
          {config.dropdownItems.map((index) => {
            const item = excelData[index];
            const isHighlighted = highlightedItem === item.name;
            const customColor = config.highlightedItems?.[index];

            return (
              <div
                key={item.name}
                className={`${styles.dropdown_item} ${isHighlighted ? styles.highlightedItem : ''}`}
                onClick={(e) => handleDropdownItemClick(item.name, e)}
                style={customColor ? { backgroundColor: customColor, color: "black" } : {}}
              >
                {item.name}
              </div>
            );
          })}
        </div>
      )}
    </div>
    </div>
  );
};
export default Block;