import React, { useState, useRef, useEffect } from 'react';
import styles from './DataModal.module.css';

// Компонент модального окна с возможностью перетаскивания
export const DataModal = ({ modalData, onClose }) => {
  // Состояние для хранения текущей позиции модального окна
  const [position, setPosition] = useState({ x: 0, y: 0 });
  // Флаг, указывающий, происходит ли перетаскивание в данный момент
  const [isDragging, setIsDragging] = useState(false);
  // Начальная позиция при начале перетаскивания
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  // Ref для доступа к DOM-элементу модального окна
  const modalRef = useRef(null);

  // Эффект для установки начальной позиции модального окна при получении данных
  useEffect(() => {
    if (modalData && modalData.position) {
      setPosition({
        x: modalData.position.left || 0,
        y: modalData.position.top || 0
      });
    }
  }, [modalData]);

  // Обработчик нажатия кнопки мыши (начало перетаскивания)
  const handleMouseDown = (e) => {
    if (e.button !== 0) return; // Реагируем только на левую кнопку мыши
    setIsDragging(true);
    // Запоминаем начальную позицию курсора относительно позиции окна
    setStartPos({
      x: e.clientX - position.x,
      y: e.clientY - position.y
    });
    e.preventDefault(); // Предотвращаем стандартное поведение браузера
  };

  // Обработчик движения мыши при перетаскивании
  const handleMouseMove = (e) => {
    if (!isDragging) return; // Если не в режиме перетаскивания, ничего не делаем
    // Обновляем позицию окна на основе движения мыши
    setPosition({
      x: e.clientX - startPos.x,
      y: e.clientY - startPos.y
    });
  };

  // Обработчик отпускания кнопки мыши (конец перетаскивания)
  const handleMouseUp = () => {
    setIsDragging(false);
  };

  // Эффект для добавления/удаления глобальных обработчиков событий мыши
  useEffect(() => {
    if (isDragging) {
      // При начале перетаскивания добавляем обработчики на весь документ
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    } else {
      // При окончании перетаскивания удаляем обработчики
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    }

    // Функция очистки - удаляем обработчики при размонтировании компонента
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, startPos]);

  // Если нет данных для отображения, не рендерим ничего
  if (!modalData) return null;

  return (
    <div className={styles.modal_overlay}>
      {/* Основной контейнер модального окна */}
      <div 
        ref={modalRef}
        className={styles.modal}
        style={{
          position: 'absolute',
          left: `${position.x}px`, // Позиция по X
          top: `${position.y}px`,  // Позиция по Y
          margin: 0,
          cursor: isDragging ? 'grabbing' : 'grab' // Меняем курсор при перетаскивании
        }}
        onMouseDown={handleMouseDown} // Обработчик начала перетаскивания
      >
        {/* Кнопка закрытия модального окна */}
        <button onClick={onClose}>Закрыть</button>
        {/* Изображение из полученных данных */}
        <img src={modalData.image} alt={modalData.name} className={styles.modal_image} />
        {/* Заголовок с именем */}
        <h2>{modalData.name}</h2>
        {/* Описание (может быть HTML) или заглушка */}
        {modalData.description ? (
          <div dangerouslySetInnerHTML={{ __html: modalData.description }} />
        ) : (
          <p>Нет описания</p>
        )}
      </div>
    </div>
  );
};

export default DataModal;