import React, { useState, useEffect, useRef } from "react";
import FloatingCard from './components/FloatingCard/FloatingCard';
import DataModal from './components/DataModal/DataModal';
import infoImage from './assets/images/info.svg';
import { blockPositions, excelData } from './data';
import { blocksConfig } from './components/FloatingCard/blocksConfig';
import './App.css';

function App() {
  // Состояния:
  const [scale, setScale] = useState(1); // Уровень масштабирования (0.5-3)
  const [modalData, setModalData] = useState(null); // Данные для модального окна
  const [searchTerm, setSearchTerm] = useState(""); // Значение поискового запроса
  const [highlightedBlock, setHighlightedBlock] = useState(null); // Выделенный блок
  const [openDropdown, setOpenDropdown] = useState(null); // Открытый дропдаун
  const [highlightedItem, setHighlightedItem] = useState(null); // Выделенное оборудование
  const [position, setPosition] = useState({ x: 0, y: 0 }); // Позиция при перетаскивании
  const [isDragging, setIsDragging] = useState(false); // Флаг перетаскивания
  const [startPos, setStartPos] = useState({ x: 0, y: 0 }); // Начальная позиция перетаскивания
  const [suggestions, setSuggestions] = useState([]); // Подсказки поиска

  // Рефы:
  const containerRef = useRef(null); // Реф основного контейнера
  const zoomContainerRef = useRef(null); // Реф масштабируемой области

  // Обработчик масштабирования колесом мыши 
  const handleWheel = (e) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.1 : 0.1;
    setScale(prev => Math.min(Math.max(prev + delta, 0.5), 3));
  };

  // Увеличение масштаба (макс. 3x)
  const zoomIn = () => setScale(prev => Math.min(prev + 0.1, 3));
  
  // Уменьшение масштаба (мин. 0.5x)
  const zoomOut = () => setScale(prev => Math.max(prev - 0.1, 0.5));

  // Закрытие модального окна
  const closeModal = () => {
    setModalData(null);
  };

  // Прокрутка к указанному блоку
  const scrollToBlock = (block) => {
    if (containerRef.current && zoomContainerRef.current) {
      const container = containerRef.current;
      const targetX = block.x * scale;
      const targetY = block.y * scale;
      const scrollX = targetX - container.clientWidth / 2;
      const scrollY = targetY - container.clientHeight / 2;
      
      container.scrollTo({
        left: scrollX,
        top: scrollY,
        behavior: 'smooth'
      });
    }
  };

  // Обработчик поиска
const handleSearch = () => {
  // Сбрасываем все текущие выделения и состояния
  setHighlightedItem(null); // Снимаем выделение с элемента
  setHighlightedBlock(null); // Снимаем выделение с блока
  setOpenDropdown(null); // Закрываем все выпадающие меню
  setSuggestions([]); // Очищаем подсказки

  // Если поисковый запрос пустой или состоит только из пробелов - выходим
  if (!searchTerm.trim()) return;

  // Нормализуем поисковый термин: приводим к нижнему регистру и удаляем все пробелы
  const lowerSearchTerm = searchTerm.toLowerCase().replace(/\s+/g, '');

  // Поиск по блокам (точные и частичные совпадения)
  const foundBlocks = Object.entries(blockPositions).filter(([key, block]) => {
    // Нормализуем данные блока для сравнения
    const blockKey = key.toLowerCase().replace(/\s+/g, '');
    const blockTitle = blocksConfig[block.ref]?.title?.toLowerCase()?.replace(/\s+/g, '');
    const blockRef = block.ref.toLowerCase().replace(/\s+/g, '');
    
    // Проверяем разные варианты совпадений:
    return blockKey === lowerSearchTerm || // Точное совпадение с ключом блока
           blockTitle === lowerSearchTerm || // Точное совпадение с заголовком блока
           blockRef === lowerSearchTerm || // Точное совпадение с ссылкой блока
           blockKey.includes(lowerSearchTerm) || // Частичное совпадение с ключом
           (blockTitle && blockTitle.includes(lowerSearchTerm)) || // Частичное совпадение с заголовком
           blockRef.includes(lowerSearchTerm); // Частичное совпадение с ссылкой
  });

  // Если блоки не найдены, ищем по элементам
  if (foundBlocks.length === 0) {
    // Фильтруем элементы данных Excel
    const foundItems = excelData.filter(item => {
      const itemName = item.name.toLowerCase().replace(/\s+/g, '');
      return itemName === lowerSearchTerm || itemName.includes(lowerSearchTerm);
    });

    // Если нашли элементы
    if (foundItems.length > 0) {
      const foundItem = foundItems[0]; // Берем первый найденный элемент
      setHighlightedItem(foundItem.name); // Выделяем найденный элемент
      setTimeout(() => setHighlightedItem(null), 2000); // Снимаем выделение через 2 секунды
      
      // Находим блок, к которому принадлежит элемент
      const blockKey = Object.keys(blockPositions).find(key => 
        blockPositions[key].ref === foundItem.blockRef
      );
      
      // Если блок найден
      if (blockKey) {
        const block = blockPositions[blockKey];
        // Выделяем блок (нормализуем имя для сравнения)
        setHighlightedBlock(blocksConfig[block.ref].name.toLowerCase().replace(/\s+/g, ''));
        setTimeout(() => setHighlightedBlock(null), 2000); // Снимаем выделение через 2 секунды
        scrollToBlock(block); // Прокручиваем к блоку
        setOpenDropdown(foundItem.blockRef); // Открываем выпадающий список блока
      }
      return;
    }
  } else {
    // Обработка найденных блоков (если нашли хотя бы один блок)
    const [blockKey, block] = foundBlocks[0]; // Берем первый найденный блок
    // Выделяем блок (нормализуем имя для сравнения)
    setHighlightedBlock(blocksConfig[block.ref].name.toLowerCase().replace(/\s+/g, ''));
    setTimeout(() => setHighlightedBlock(null), 2000); // Снимаем выделение через 2 секунды
    scrollToBlock(block); // Прокручиваем к блоку
    
    // Если у блока есть выпадающие элементы - открываем их
    if (blocksConfig[block.ref]?.dropdownItems) {
      setOpenDropdown(block.ref);
    }
  }
};

// Обработчик изменений в поле поиска (вызывается при каждом изменении текста)
const handleSearchChange = (e) => {
  const value = e.target.value; // Получаем текущее значение поля поиска
  setSearchTerm(value); // Обновляем состояние поискового термина
  
  // Показываем подсказки только если введено более 2 символов
  if (value.length > 2) {
    const lowerValue = value.toLowerCase().replace(/\s+/g, ''); // Нормализуем значение
    
    // Собираем все возможные варианты для подсказок:
    const blockNames = Object.keys(blockPositions); // Имена блоков
    const blockTitles = Object.values(blockPositions)
      .map(b => blocksConfig[b.ref]?.title) // Заголовки блоков
      .filter(Boolean); // Удаляем пустые значения
    const itemNames = excelData.map(item => item.name); // Имена элементов
    
    // Объединяем все варианты и убираем дубликаты
    const allOptions = [...blockNames, ...blockTitles, ...itemNames];
    const uniqueOptions = [...new Set(allOptions)];
    
    // Фильтруем варианты, оставляя только те, которые содержат поисковый термин
    setSuggestions(
      uniqueOptions.filter(option => 
        option.toLowerCase().replace(/\s+/g, '').includes(lowerValue))
    );
  } else {
    setSuggestions([]); // Если символов меньше 3 - очищаем подсказки
  }
};

  // Обработчики перетаскивания
  const handleMouseDown = (e) => {
    if (e.button !== 0) return;
    setIsDragging(true);
    setStartPos({
      x: e.clientX - position.x,
      y: e.clientY - position.y
    });
    zoomContainerRef.current.classList.add('grabbing');
    e.preventDefault();
  };

  const handleMouseMove = (e) => {
    if (!isDragging) return;
    setPosition({
      x: e.clientX - startPos.x,
      y: e.clientY - startPos.y
    });
  };

  const handleMouseUp = () => {
    setIsDragging(false);
    if (zoomContainerRef.current) {
      zoomContainerRef.current.classList.remove('grabbing');
    }
  };

  useEffect(() => {
    const container = containerRef.current;
    container.addEventListener("wheel", handleWheel, { passive: false });
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseup', handleMouseUp);

    return () => {
      container.removeEventListener("wheel", handleWheel);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, startPos]);

  return (
    <>
      <div className="controls-container">
        <div className="info-container">
          <img src={infoImage} alt="Информация" className="info-image" />
        </div>
        <div className="search-zoom">
        <div className="search-container">
          <input
            type="text"
            value={searchTerm}
            onChange={handleSearchChange}
            placeholder="Поиск оборудования..."
            onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
          />
          {suggestions.length > 0 && (
            <div className="suggestions">
              {suggestions.slice(0, 5).map((item, i) => (
                <div 
                  key={i} 
                  className="suggestion-item"
                  onClick={() => {
                    setSearchTerm(item);
                    setSuggestions([]);
                    handleSearch();
                  }}
                >
                  {item}
                </div>
              ))}
            </div>
          )}
          <button className="search-button" onClick={handleSearch}>
            Поиск
          </button>
          <button 
            className="clear-button" 
            onClick={() => {
              setSearchTerm("");
              setHighlightedItem(null);
              setHighlightedBlock(null);
              setOpenDropdown(null);
              setSuggestions([]);
            }}
          >
            Очистить
          </button>
        </div>
        
        <div className="zoom-controls">
          <button className="zcontrols" onClick={zoomOut}>-</button>
          <button className="zcontrols" onClick={zoomIn}>+</button>
        </div>
      </div>
      </div>
      <div className="app-container" ref={containerRef}>
        <div 
          ref={zoomContainerRef}
          className="zoom-container" 
          style={{ 
            transform: `translate(${position.x}px, ${position.y}px) scale(${scale})`,
            '--scale': scale
          }}
          onMouseDown={handleMouseDown}
        >
          <FloatingCard 
            setModalData={setModalData}
            highlightedBlock={highlightedBlock}
            openDropdown={openDropdown}
            highlightedItem={highlightedItem}
          />
        </div>
      </div>
      
      <DataModal 
        modalData={modalData} 
        onClose={closeModal}
      />
    </>
  );
}

export default App;